import {config} from './config.js';
import {acceptedItems,financialTotals,hasRejectedItems,rejectedItems,summarizeMonth,todayBangkok,totals,transition,validateItems,validatePODate} from './domain.js';
export const configured=Boolean(config.supabaseUrl&&config.publishableKey);
let session=null,profile=null,refreshPromise=null,recovery=null;
const sessionStorageKey='po-the-grands-supabase-session-v1';
function clearSession(){session=null;profile=null;try{globalThis.localStorage?.removeItem(sessionStorageKey);}catch{}}
function saveSession(data){const next={...data,expires_at:data.expires_at||Date.now()/1000+data.expires_in};try{globalThis.localStorage?.setItem(sessionStorageKey,JSON.stringify(next));}catch{throw Error('เบราว์เซอร์บันทึก session ไม่ได้ กรุณาตรวจการตั้งค่าพื้นที่จัดเก็บข้อมูล');}session=next;}
async function request(path,{method='GET',body,auth=true,headers={},timeoutMs=15000}={}){if(auth&&session&&Date.now()/1000>session.expires_at-60)await refresh();let response;try{response=await fetch(config.supabaseUrl.replace(/\/$/,'')+path,{method,headers:{apikey:config.publishableKey,...(auth&&session?{Authorization:`Bearer ${session.access_token}`} :{}),'Content-Type':'application/json',...headers},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(timeoutMs)});}catch{throw Error(path.startsWith('/auth/')?'เชื่อมต่อเพื่อเข้าสู่ระบบไม่ได้หรือหมดเวลารอ กรุณาลองเข้าสู่ระบบอีกครั้ง':'เชื่อมต่อไม่ได้หรือหมดเวลารอ กรุณาลองอีกครั้งด้วยคำขอเดิมเพื่อป้องกันรายการซ้ำ');}const data=await response.json().catch(()=>null);if(!response.ok){if((response.status===401&&auth)||(path.includes('grant_type=refresh_token')&&response.status===400)){clearSession();throw Object.assign(Error('หมดเวลาเข้าสู่ระบบ กรุณาเข้าสู่ระบบอีกครั้ง ข้อมูลที่กรอกยังอยู่'),{authExpired:true});}throw Error(data?.message||data?.msg||data?.error_description||'บันทึกไม่ได้ กรุณาลองอีกครั้ง');}return {data,response};}
async function refresh(){if(!session)throw Error('กรุณาเข้าสู่ระบบ');if(!refreshPromise)refreshPromise=request('/auth/v1/token?grant_type=refresh_token',{method:'POST',auth:false,body:{refresh_token:session.refresh_token}}).then(r=>saveSession(r.data)).finally(()=>{refreshPromise=null;});await refreshPromise;}
export const api={
 async login(username,password){const entered=String(username||'').trim().toLowerCase();const options=entered.includes('@')?{path:'/auth/v1/token?grant_type=password',body:{email:entered,password}}:{path:'/functions/v1/owner-account',body:{action:'login',username:entered,password}};const {data}=await request(options.path,{method:'POST',auth:false,body:options.body,timeoutMs:45000});saveSession(data);const p=await request('/rest/v1/profiles?id=eq.'+encodeURIComponent(data.user.id)+'&select=id,role,display_name,login_email,login_name,can_export_report',{timeoutMs:45000});if(!p.data?.length){clearSession();throw Error('บัญชีนี้ยังไม่ได้รับสิทธิ์ใช้งาน กรุณาติดต่อเจ้าของ');}profile=p.data[0];return profile;},
 async updateOwnerLoginName({username,currentPassword}){const {data}=await request('/functions/v1/owner-account',{method:'POST',body:{action:'update-login-name',username,currentPassword},timeoutMs:45000});profile={...profile,...data.user};return profile;},
 async changeOwnerPassword({currentPassword,newPassword}){const {data}=await request('/functions/v1/owner-account',{method:'POST',body:{action:'change-password',currentPassword,newPassword},timeoutMs:45000});clearSession();return data;},
 async requestOwnerRecovery(username){return (await request('/functions/v1/owner-account',{method:'POST',auth:false,body:{action:'request-recovery',username:String(username||'').trim().toLowerCase()},timeoutMs:45000})).data;},
 async beginOwnerRecovery(hash){recovery=null;const params=new URLSearchParams(String(hash||'').replace(/^#/,''));const token=params.get('access_token');const expires=Number(params.get('expires_in'));if(params.get('type')!=='recovery'||!token||!Number.isFinite(expires)||expires<=0||params.has('error'))return false;const candidate={token,expires:Date.now()/1000+expires};const headers={Authorization:`Bearer ${token}`};try{const {data:user}=await request('/auth/v1/user',{auth:false,headers});if(!user?.id)return false;const {data:rows}=await request('/rest/v1/profiles?id=eq.'+encodeURIComponent(user.id)+'&role=eq.owner&deleted_at=is.null&select=id,role',{auth:false,headers});if(rows?.length!==1||rows[0].id!==user.id||rows[0].role!=='owner')return false;recovery=candidate;return true;}catch{throw Error('ลิงก์ใช้ไม่ได้หรือเชื่อมต่อไม่ได้ กรุณาขอลิงก์ใหม่แล้วลองอีกครั้ง');}},
 cancelOwnerRecovery(){const token=recovery?.token;recovery=null;if(token)void request('/auth/v1/logout?scope=local',{method:'POST',auth:false,headers:{Authorization:`Bearer ${token}`}}).catch(()=>{});},
 async resetOwnerRecovery(newPassword){if(String(newPassword).length<6)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');if(!recovery||Date.now()/1000>=recovery.expires){recovery=null;throw Error('ลิงก์หมดอายุ กรุณาขอลิงก์ใหม่');}const headers={Authorization:`Bearer ${recovery.token}`};await request('/auth/v1/user',{method:'PUT',auth:false,headers,body:{password:newPassword},timeoutMs:45000});recovery=null;clearSession();try{await request('/auth/v1/logout?scope=global',{method:'POST',auth:false,headers});}catch{}return {ok:true};},
 async restoreSession(){let saved;try{saved=globalThis.localStorage?.getItem(sessionStorageKey);}catch{throw Error('อ่าน session จากเบราว์เซอร์ไม่ได้ กรุณาตรวจการตั้งค่าพื้นที่จัดเก็บข้อมูล');}if(!saved)return null;try{session=JSON.parse(saved);if(!session?.access_token||!session?.refresh_token||!session?.user?.id||!Number.isFinite(Number(session.expires_at)))throw Error('invalid session');}catch{clearSession();return null;}try{if(Date.now()/1000>session.expires_at-60)await refresh();const p=await request('/rest/v1/profiles?id=eq.'+encodeURIComponent(session.user.id)+'&select=id,role,display_name,login_email,login_name,can_export_report');if(!p.data?.length){clearSession();return null;}profile=p.data[0];return profile;}catch(e){if(e.authExpired){clearSession();return null;}throw e;}},
 async logout(){try{if(session)await request('/auth/v1/logout',{method:'POST'});}finally{clearSession();}},
 async list(status,page=1,scope='all'){const effectiveScope=profile?.role==='office'&&!profile.can_export_report?'mine':scope;return (await request('/rest/v1/rpc/list_po',{method:'POST',body:{p_status:status||null,p_page:page,p_scope:effectiveScope}})).data;},
 async stats(scope='all'){const own=profile?.role==='office'&&(!profile.can_export_report||scope==='mine');return (await request('/rest/v1/rpc/po_counts',{method:'POST',body:{p_mine:own}})).data;},
 async detail(id){const {data}=await request('/rest/v1/purchase_orders?id=eq.'+encodeURIComponent(id)+'&select=*');if(!data?.length)throw Error('ไม่พบใบ PO หรือไม่มีสิทธิ์เข้าถึง');const events=await request('/rest/v1/po_events?po_id=eq.'+encodeURIComponent(id)+'&select=*&order=at.asc');return {...data[0],items:(data[0].items||[]).map((item,index)=>({...item,line_no:Number(item.line_no||index+1)})),events:events.data};},
 async create(items,po_date,key,department){return (await request('/rest/v1/rpc/create_po',{method:'POST',body:{p_items:items,p_po_date:po_date,p_request_id:key,p_department:department}})).data;},
 async action(po,action,reason,confirmed,key){if(action==='approve')return this.decidePO({poId:po.id,expectedVersion:po.version,rejectedLineNos:[],reason:'',approvalNote:reason,key});if(action==='reject')return this.decidePO({poId:po.id,expectedVersion:po.version,rejectedLineNos:(po.items||[]).map((item,index)=>Number(item.line_no||index+1)),reason,approvalNote:'',key});return (await request('/rest/v1/rpc/act_on_po',{method:'POST',body:{p_id:po.id,p_action:action,p_version:po.version,p_reason:reason,p_invoice_confirmed:confirmed,p_request_id:key}})).data;},
 async unlockPO(poId,expectedVersion,key){return (await request('/rest/v1/rpc/unlock_po_edit',{method:'POST',body:{p_id:poId,p_version:expectedVersion,p_request_id:key}})).data;},
 async lockPO(poId,token){return (await request('/rest/v1/rpc/lock_po_edit',{method:'POST',body:{p_id:poId,p_token:token}})).data;},
 async editPO({poId,expectedVersion,token,items,key}){const editable=(items||[]).map(({line_no,department,name,spec,source,note,qty,unit,unit_price,vat,payment_method})=>({line_no,department,name,spec,source,note,qty,unit,unit_price,vat,...(payment_method===undefined?{}:{payment_method})}));return (await request('/rest/v1/rpc/edit_po_items',{method:'POST',body:{p_id:poId,p_version:expectedVersion,p_token:token,p_items:editable,p_request_id:key}})).data;},
 async decidePO({poId,expectedVersion,rejectedLineNos=[],reason='',approvalNote='',key}){return (await request('/rest/v1/rpc/decide_po_items',{method:'POST',body:{p_id:poId,p_version:expectedVersion,p_rejected_line_nos:rejectedLineNos,p_reason:reason,p_approval_note:approvalNote,p_request_id:key}})).data;},
 async report(month){return (await request('/rest/v1/rpc/monthly_po_report',{method:'POST',body:{p_month:month+'-01'}})).data;},
 async departments(){const {data}=await request('/rest/v1/departments?select=name&archived_at=is.null&order=name.asc');return data.map(row=>row.name);},
 async addDepartment(name){return request('/rest/v1/rpc/manage_department',{method:'POST',body:{p_action:'add',p_name:name}});},
 async archiveDepartment(name){return request('/rest/v1/rpc/manage_department',{method:'POST',body:{p_action:'archive',p_name:name}});},
 async notifications(){return (await request('/rest/v1/notifications?select=*&order=created_at.desc&limit=100')).data;},
 async markNotificationsRead(){return request('/rest/v1/notifications?read_at=is.null',{method:'PATCH',body:{read_at:new Date().toISOString()},headers:{Prefer:'return=minimal'}});},
 async users(){return (await request('/functions/v1/manage-user',{method:'POST',body:{action:'list'}})).data.users;},
 async saveOffice(account){return (await request('/functions/v1/manage-user',{method:'POST',body:{action:'upsert',...account}})).data.user;},
 async deleteUser(account){return (await request('/functions/v1/manage-user',{method:'POST',body:{action:'delete',profile_id:account.id}})).data.user;}
};

const demoStorage='po-the-grands-demo-accounts-v1';
const toHex=bytes=>[...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('');
async function hashPassword(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return toHex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},material,256));}
function demoAccounts(){try{return JSON.parse(localStorage.getItem(demoStorage)||'[]');}catch{return [];}}
function saveDemoAccounts(accounts){localStorage.setItem(demoStorage,JSON.stringify(accounts));}
export const demoAuth={
 needsSetup(){return demoAccounts().length===0;},
 async setupOwner(password){if(!this.needsSetup())throw Error('ตั้งค่าบัญชีเจ้าของแล้ว');if(password.length<6)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');const salt=crypto.randomUUID(),password_hash=await hashPassword(password,salt);const owner={id:'demo-owner',username:'owner',display_name:'เจ้าของ',role:'owner',salt,password_hash};saveDemoAccounts([owner]);return {...owner,password_hash:undefined,salt:undefined};},
 async resetOwner(password){if(password.length<6)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');const accounts=demoAccounts(),owner=accounts.find(a=>a.role==='owner'||a.username==='owner');if(!owner)throw Error('ยังไม่มีบัญชีเจ้าของ');const salt=crypto.randomUUID(),password_hash=await hashPassword(password,salt);Object.assign(owner,{salt,password_hash});saveDemoAccounts(accounts);return {id:owner.id,username:owner.username,display_name:owner.display_name,role:owner.role};},
 async login(username,password){const normalized=String(username).trim().toLowerCase();const account=demoAccounts().find(a=>a.username.toLowerCase()===normalized||a.display_name.toLowerCase()===normalized);if(!account||await hashPassword(password,account.salt)!==account.password_hash)throw Error('ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง — ใช้ชื่อบัญชี');return {id:account.id,username:account.username,display_name:account.display_name,role:account.role,can_export_report:account.can_export_report===true};},
 list(actor){if(actor?.role!=='owner')throw Error('เฉพาะเจ้าของเท่านั้นที่จัดการผู้ใช้งานได้');return demoAccounts().filter(a=>a.role==='office').map(({password_hash,salt,...a})=>({...a,can_export_report:a.can_export_report===true}));},
 async saveOffice(actor,{username,display_name,password}){if(actor?.role!=='owner')throw Error('เฉพาะเจ้าของเท่านั้นที่จัดการผู้ใช้งานได้');username=String(username||'').trim().toLowerCase();display_name=String(display_name||'').trim();if(!/^[a-z0-9._-]{3,50}$/.test(username))throw Error('ชื่อผู้ใช้ใช้ a-z, 0-9, จุด ขีด และขีดล่าง 3–50 ตัว');if(!display_name||display_name.length>100)throw Error('ระบุชื่อที่แสดงไม่เกิน 100 ตัวอักษร');const accounts=demoAccounts(),existing=accounts.find(a=>a.username===username);if(password==='__KEEP__')password='';if(!existing&&String(password||'').length<8)throw Error('บัญชีใหม่ต้องมีรหัสผ่านอย่างน้อย 6 ตัวอักษร');let next={id:existing?.id||crypto.randomUUID(),username,display_name,role:'office'};if(password){if(String(password).length<8)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');const salt=crypto.randomUUID();next={...next,salt,password_hash:await hashPassword(password,salt)};}else next={...existing,...next};const index=existing?accounts.indexOf(existing):-1;if(index>=0)accounts[index]=next;else accounts.push(next);saveDemoAccounts(accounts);return {id:next.id,username,display_name,role:'office'};}
};

export function makeDemo(){const office={id:'demo-office',role:'office',display_name:'ออฟฟิศ'};const samples=[['กระดาษถ่ายเอกสาร A4','80 แกรม ขนาด A4 บรรจุ 500 แผ่น / รีม','ร้านเครื่องเขียนเชียงใหม่','10','214',true,'pending'],['อุปกรณ์สำนักงาน','ปากกาลูกลื่นสีน้ำเงิน บรรจุ 12 ด้าม / กล่อง','ห้างค้าส่ง','4','214',true,'pending'],['หมึกเครื่องพิมพ์','ตลับหมึกสีดำ รุ่น 85A','ตัวแทนจำหน่าย HP','2','1605',true,'approved'],['ชั้นจัดเก็บเอกสาร','ชั้นเหล็ก 4 ชั้น ขนาด 90 × 45 × 180 ซม.','ร้านเฟอร์นิเจอร์สำนักงาน','1','4815',true,'received'],['กล่องจัดเก็บเอกสาร','กล่องกระดาษแข็ง ขนาด A4','ร้านเครื่องเขียนเชียงใหม่','6','100',false,'closed']];let rows=samples.map((s,n)=>{const items=validateItems([{name:s[0],spec:s[1],source:s[2],note:'',qty:s[3],unit_price:s[4],vat:s[5]}]);let p={id:'demo-sample-'+n,po_number:'DEMO-2026-'+String(5-n).padStart(5,'0'),po_date:new Date(Date.now()-n*86400000).toISOString().slice(0,10),created_at:new Date(Date.now()-n*86400000).toISOString(),created_by:office.id,requester_name:office.display_name,status:'pending',items,...totals(items),version:1,events:[{action:'create',actor_name:office.display_name,at:new Date(Date.now()-n*86400000).toISOString()}]};if(n>=2)p=transition(p,'approve',{role:'owner',display_name:'เจ้าของ'});if(n>=3)p=transition(p,'receive',office);if(n>=4)p=transition(p,'close',{role:'owner',display_name:'เจ้าของ'},'',true);return p;});try{const stored=JSON.parse(localStorage.getItem('po-the-grands-demo-orders-v1')||'[]');if(Array.isArray(stored))rows.push(...stored);}catch{}const persist=()=>localStorage.setItem('po-the-grands-demo-orders-v1',JSON.stringify(rows.filter(row=>row.created_by!=='demo-office')));const commands=new Map();return {async list(status,page=1){const result=rows.filter(r=>!status||r.status===status);return {rows:result.slice((page-1)*10,page*10),total:result.length};},async departments(){const key='po-the-grands-demo-departments-v1',fallback=['อาหาร','ของหวาน','ผลไม้','ติ่มซำ','แซนวิช','สลัด','ครัวกลาง','แม่บ้าน','ออฟฟิศ','ช่าง','ภูดอย','บ้านโจ้','ท่ารั้ว'];try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch{return fallback}},async stats(){return Object.fromEntries(['pending','approved','received','closed','rejected'].map(s=>[s,rows.filter(r=>r.status===s).length]));},async detail(id){return structuredClone(rows.find(r=>r.id===id));},async create(items,po_date,key,actor,department){if(commands.has(key))return commands.get(key);const normalized=validateItems(items),now=new Date().toISOString();const p={id:crypto.randomUUID(),po_number:'DEMO-2026-'+String(rows.length+1).padStart(5,'0'),po_date:validatePODate(po_date),created_at:now,created_by:actor.id,requester_name:actor.display_name,department:department||'',status:'pending',items:normalized,...totals(normalized),version:1,events:[{action:'create',actor_name:actor.display_name,at:now}]};rows.unshift(p);persist();commands.set(key,p);return p;},async action(po,action,reason,confirmed,key,currentActor){if(commands.has(key))return commands.get(key);const ix=rows.findIndex(r=>r.id===po.id);if(rows[ix].version!==po.version)throw Error('สถานะเปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');rows[ix]=transition(rows[ix],action,currentActor,reason,confirmed);persist();commands.set(key,rows[ix]);return rows[ix];},async report(month){return summarizeMonth(rows.filter(r=>r.po_date.startsWith(month)));},async users(actor){return demoAuth.list(actor);},async saveOffice(account,actor){return demoAuth.saveOffice(actor,account);}};}

const makeDemoWithoutOwnerWorkflow=makeDemo;
makeDemo=function(){
  const service=makeDemoWithoutOwnerWorkflow(),baseList=service.list.bind(service),baseDetail=service.detail.bind(service),baseReport=service.report.bind(service),baseAction=service.action.bind(service);
  const workflowKey='po-the-grands-demo-owner-workflow-v1',notificationKey='po-the-grands-notifications-v1',unlocked=new Map(),unlockRequests=new Map();
  let currentActor=null;
  const clone=value=>structuredClone(value);
  const fingerprint=async value=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(value))))].map(byte=>byte.toString(16).padStart(2,'0')).join('');
  const read=()=>{try{const value=JSON.parse(localStorage.getItem(workflowKey)||'null');return value?.schema===1&&value.overlays&&Array.isArray(value.audit)&&value.commands?value:{schema:1,overlays:{},audit:[],commands:{}};}catch{return {schema:1,overlays:{},audit:[],commands:{}};}};
  const write=value=>localStorage.setItem(workflowKey,JSON.stringify(value));
  const owner=()=>{if(currentActor?.role!=='owner'||!currentActor.id)throw Error('เฉพาะเจ้าของเท่านั้นที่ดำเนินการนี้ได้');return currentActor;};
  const command=(env,key,payload)=>{const old=env.commands[key];if(!old)return null;if(old.payload!==JSON.stringify(payload))throw Error('หมายเลขคำขอนี้ใช้กับข้อมูลอื่นแล้ว');return clone(old.result);};
  const persistResult=(env,key,payload,result)=>{env.commands[key]={payload:JSON.stringify(payload),result:clone(result)};write(env);return clone(result);};
  const findOverlay=(env,base)=>env.overlays[base.id]||Object.values(env.overlays).find(row=>row.po_number===base.po_number);
  const baseRows=async()=>{const first=await baseList('',1),rows=[...first.rows];for(let page=2;rows.length<first.total;page++){const next=await baseList('',page);if(!next.rows.length)break;rows.push(...next.rows);}return rows;};
  const current=async id=>{const env=read(),direct=env.overlays[id];let base=await baseDetail(id);if(!base&&direct)base=(await baseRows()).find(row=>row.po_number===direct.po_number);if(!base)throw Error('ไม่พบใบ PO');const overlay=direct||findOverlay(env,base);if(overlay&&overlay.po_number!==base.po_number)throw Error('ข้อมูลใบ PO ไม่ตรงกัน');return clone(overlay||base);};
  const allRows=async()=>{const env=read();return (await baseRows()).map(row=>findOverlay(env,row)||row);};
  service.setActor=actor=>{if(currentActor?.id!==actor?.id||currentActor?.role!==actor?.role){unlocked.clear();unlockRequests.clear();}currentActor=actor?{id:actor.id,role:actor.role,display_name:actor.display_name,can_export_report:actor.can_export_report===true}:null;};
  service.list=async(status,page=1)=>{let rows=await allRows();if(status==='rejected')rows=rows.filter(hasRejectedItems).map(po=>{const items=rejectedItems(po);return {...clone(po),real_status:po.status,status:'rejected',items,...totals(items)};});else if(status)rows=rows.filter(po=>po.status===status);return {rows:rows.slice((page-1)*10,page*10),total:rows.length};};
  service.stats=async()=>{const rows=await allRows();return Object.fromEntries(['pending','approved','received','closed','rejected'].map(status=>[status,status==='rejected'?rows.filter(hasRejectedItems).length:rows.filter(po=>po.status===status).length]));};
  service.detail=async id=>{const listed=(await allRows()).find(row=>row.id===id),po=listed||await current(id);return {...po,items:(po.items||[]).map((item,index)=>({...item,line_no:Number(item.line_no||index+1)}))};};
  service.report=async month=>{const result=await baseReport(month),env=read(),rows=(result.rows||[]).map(row=>findOverlay(env,row)||row).filter(row=>String(row.po_date||'').startsWith(month)).map(po=>({...po,items:acceptedItems(po).map((item,index)=>({...item,line_no:Number(item.line_no||index+1)})),...financialTotals(po),edit_history:(po.events||[]).filter(event=>event.action==='owner_edit')}));return {...summarizeMonth(rows),rows};};
  service.action=async(po,action,reason,confirmed,key,actor)=>{if(!['receive','close'].includes(action))return baseAction(po,action,reason,confirmed,key,actor);const env=read(),payload={action:'lifecycle',poId:po.id,decision:action,version:po.version,reason,confirmed,actorId:actor?.id},cached=command(env,key,payload);if(cached)return cached;const latest=await current(po.id);if(latest.version!==po.version)throw Error('สถานะเปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');const updated=transition(latest,action,actor,reason,confirmed);env.overlays[po.id]=clone(updated);return persistResult(env,key,payload,updated);};
  service.unlockPO=async(poId,expectedVersion,key)=>{const actor=owner(),cacheKey=`${actor.id}:${key}`,payload=JSON.stringify({poId,expectedVersion});const cached=unlockRequests.get(cacheKey);if(cached){if(cached.payload!==payload)throw Error('หมายเลขคำขอนี้ใช้กับข้อมูลอื่นแล้ว');if(cached.expires<Date.now())throw Error('รายการถูกล็อกหรือหมดเวลาปลดล็อก กรุณาปลดล็อกใหม่');return clone(cached.result);}const po=await current(poId);if(po.version!==expectedVersion)throw Error('ข้อมูลใบ PO เปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');if(!['pending','approved','received'].includes(po.status)||!acceptedItems(po).length)throw Error('ใบ PO นี้ไม่มีรายการที่แก้ไขได้');const token=crypto.randomUUID(),expires=Date.now()+600000,result={token,version:po.version};unlocked.set(poId,{token,actorId:actor.id,version:po.version,expires});unlockRequests.set(cacheKey,{payload,result,expires,poId});return result;};
  service.lockPO=async(poId,token)=>{const actor=owner(),lease=unlocked.get(poId);if(lease?.token===token&&lease.actorId===actor.id){unlocked.delete(poId);for(const [key,value] of unlockRequests)if(value.poId===poId&&value.result.token===token)unlockRequests.delete(key);}return true;};
  service.editPO=async({poId,expectedVersion,token,items,key})=>{const actor=owner(),env=read(),itemsForEdit=(items||[]).map(({line_no,department,name,spec,source,note,qty,unit,unit_price,vat,payment_method})=>({line_no,department,name,spec,source,note,qty,unit,unit_price,vat,...(payment_method===undefined?{}:{payment_method})})),payload={action:'edit',poId,expectedVersion,token_fingerprint:await fingerprint(token),items:itemsForEdit},cached=command(env,key,payload);if(cached)return cached;const po=await current(poId),lease=unlocked.get(poId);if(po.version!==expectedVersion)throw Error('ข้อมูลใบ PO เปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');if(!['pending','approved','received'].includes(po.status))throw Error('ใบ PO นี้แก้ไขไม่ได้');if(!lease||lease.token!==token||lease.actorId!==actor.id||lease.version!==po.version||lease.expires<Date.now())throw Error('รายการถูกล็อกหรือหมดเวลาปลดล็อก กรุณาปลดล็อกใหม่');const editable=po.items.map((item,index)=>item.decision==='rejected'?-1:index).filter(index=>index>=0);if(!Array.isArray(items)||itemsForEdit.length!==editable.length)throw Error('แก้ไขได้เฉพาะรายการที่ยังดำเนินการ และห้ามเพิ่มหรือลบรายการ');const validated=validateItems(itemsForEdit.map((item,index)=>{if(Number(item.line_no)!==editable[index]+1)throw Error('ลำดับรายการเปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');if(['id','item_id','decision','decision_reason','decision_at','decision_by','order'].some(key=>Object.hasOwn(item,key)))throw Error('แก้ไขรหัส ลำดับ หรือผลอนุมัติของรายการไม่ได้');return item;}));let position=0;const nextItems=po.items.map((old,index)=>{if(old.decision==='rejected')return clone(old);const next={...validated[position++],line_no:index+1};for(const key of ['decision','decision_reason','decision_at','decision_by'])if(old[key]!==undefined)next[key]=old[key];return next;});const editFields=['department','name','spec','source','note','qty','unit','unit_price','vat','payment_method'],normalizeEditValue=(key,value)=>key==='qty'||key==='unit_price'?Number(value):key==='payment_method'?value||null:value,hasChanges=editable.some((line,index)=>editFields.some(field=>normalizeEditValue(field,po.items[line][field])!==normalizeEditValue(field,nextItems[line][field])));if(!hasChanges){unlocked.delete(poId);return persistResult(env,key,payload,po);}const before=po.items.map((item,index)=>({...clone(item),line_no:Number(item.line_no||index+1)})),after=nextItems.map((item,index)=>({...clone(item),line_no:Number(item.line_no||index+1)})),beforeTotal=financialTotals(po).total_cents,next={...po,items:nextItems,...financialTotals({...po,items:nextItems}),version:po.version+1};const delta=next.total_cents-beforeTotal,event={action:'owner_edit',actor_id:actor.id,actor_name:actor.display_name,at:new Date().toISOString(),before_items:before,after_items:after,before_total_cents:beforeTotal,after_total_cents:next.total_cents,item_amount_delta_cents:delta,amount_delta_cents:delta};next.events=[...(po.events||[]),event];env.overlays[po.id]=clone(next);env.audit.push({po_id:po.id,po_number:po.po_number,...event});delete env.commands[key];unlocked.delete(poId);const rows=JSON.parse(localStorage.getItem(notificationKey)||'[]'),event_key=`${po.id}:owner_edit:${next.version}`;if(!rows.some(row=>row.event_key===event_key))rows.unshift({id:crypto.randomUUID(),event_key,po_id:po.id,recipient_role:'office',recipient_id:po.created_by,title:'เจ้าของแก้ไขรายการในใบ PO',message:`${po.po_number} มีการแก้ไขรายการโดยเจ้าของ`,action:'owner_edit',created_at:event.at,read_at:null});localStorage.setItem(notificationKey,JSON.stringify(rows));return persistResult(env,key,payload,next);};
  service.decidePO=async({poId,expectedVersion,rejectedLineNos=[],reason='',approvalNote='',key})=>{const actor=owner(),env=read(),payload={action:'decide',poId,expectedVersion,rejectedLineNos,reason,approvalNote},cached=command(env,key,payload);if(cached)return cached;const po=await current(poId);if(po.version!==expectedVersion)throw Error('ข้อมูลใบ PO เปลี่ยนแล้ว กรุณาโหลดข้อมูลล่าสุด');if(po.status!=='pending')throw Error('พิจารณาได้เฉพาะใบ PO ที่รออนุมัติ');const rejected=[...new Set(rejectedLineNos.map(Number))];if(rejected.some(line=>!Number.isInteger(line)||line<1||line>po.items.length))throw Error('รายการสินค้าที่เลือกไม่ถูกต้อง');const cleanReason=String(reason||'').trim(),cleanNote=String(approvalNote||'').trim();if(rejected.length&&!cleanReason)throw Error('ระบุเหตุผลของรายการที่ไม่อนุมัติ');if(cleanReason.length>2000||cleanNote.length>2000)throw Error('ข้อความต้องไม่เกิน 2,000 ตัวอักษร');const allRejected=rejected.length===po.items.length,at=new Date().toISOString(),items=po.items.map((item,index)=>({...clone(item),line_no:index+1,decision:rejected.includes(index+1)?'rejected':'approved',decision_reason:rejected.includes(index+1)?cleanReason:'',decision_at:at,decision_by:actor.id})),next={...po,status:allRejected?'rejected':'approved',items,...totals(items.filter(item=>item.decision!=='rejected')),version:po.version+1,approved_at:allRejected?po.approved_at:at,rejection_reason:allRejected?cleanReason:null,approval_note:allRejected?null:cleanNote||null};const event={action:allRejected?'reject':'approve',actor_id:actor.id,actor_name:actor.display_name,at,reason:allRejected?cleanReason:'',rejected_line_nos:rejected,approval_note:next.approval_note,before_items:null,after_items:null,before_total_cents:null,after_total_cents:null,item_amount_delta_cents:null,amount_delta_cents:null};next.events=[...(po.events||[]),event];env.overlays[po.id]=clone(next);env.audit.push({po_id:po.id,po_number:po.po_number,...event});persistResult(env,key,payload,next);return next;};
  return service;
};
demoAuth.saveOffice=async function(actor,{username,display_name,password,id,can_export_report}){if(actor?.role!=='owner')throw Error('เฉพาะเจ้าของเท่านั้นที่จัดการผู้ใช้งานได้');username=String(username||'').trim();display_name=String(display_name||'').trim();if(!/^[a-z0-9._]+$/.test(username.toLowerCase()))throw Error('ชื่อผู้ใช้ใช้ตัวอังกฤษ ตัวเลข จุด หรือขีดล่าง');username=username.toLowerCase();if(!display_name||display_name.length>100)throw Error('ระบุชื่อที่แสดงไม่เกิน 100 ตัวอักษร');const accounts=demoAccounts(),existing=id?accounts.find(a=>a.id===id):accounts.find(a=>a.username===username);if(password==='__KEEP__')password='';if(!existing&&String(password||'').length<6)throw Error('บัญชีใหม่ต้องใช้รหัสผ่านอย่างน้อย 6 ตัวอักษร');let next={...existing,id:existing?.id||crypto.randomUUID(),username,display_name,role:'office',can_export_report:can_export_report===true};if(password){if(String(password).length<6)throw Error('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');const salt=crypto.randomUUID();next={...next,salt,password_hash:await hashPassword(password,salt)};}const index=existing?accounts.indexOf(existing):-1;if(index>=0)accounts[index]=next;else accounts.push(next);saveDemoAccounts(accounts);return {id:next.id,username,display_name,role:'office',can_export_report:next.can_export_report};};
demoAuth.deleteUser=async function(actor,target){if(actor?.role!=='owner')throw Error('เฉพาะเจ้าของเท่านั้นที่จัดการผู้ใช้งานได้');if(!target?.id||target.role!=='office')throw Error('ไม่สามารถลบบัญชีนี้ได้');const accounts=demoAccounts(),index=accounts.findIndex(a=>a.id===target.id);if(index<0)throw Error('ไม่พบบัญชีที่ต้องการลบ');accounts.splice(index,1);saveDemoAccounts(accounts);return {id:target.id};};
